    const options=Array.isArray(question.options)?question.options:[],answer=Number(question.answer)||0,imageId=String(question.imageFileId||'');
    const row=document.createElement('div');row.className='mk-course-exam-question card';
    row.innerHTML=`<div class="section-head"><b>سؤال ${box.children.length+1}</b><button type="button" class="btn danger" data-mk-click="mkRemoveCourseExamQuestionRow(this)">حذف السؤال</button></div>
      <label>نص السؤال <span class="small muted">(اتركه فارغًا إذا كانت الصورة تحتوي السؤال كاملًا)</span><textarea class="mk-course-exam-text" rows="2" maxlength="10000" placeholder="اكتب السؤال هنا إن كان نصيًا">${esc(question.text||'')}</textarea></label>
      <label>صورة السؤال (اختياري)<input class="mk-course-exam-image" type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-mk-change="mkPreviewCourseExamQuestionImage(this)"><span class="small muted">JPG أو PNG أو WebP أو GIF — حتى 5MB</span></label>
      ${imageId?`<input class="mk-course-exam-existing-image" type="hidden" value="${esc(imageId)}"><div class="mk-course-exam-image-preview"><img class="assignment-question-img" data-mk-file-ref="${esc(imageId)}" alt="صورة السؤال الحالية"><button type="button" class="btn" data-mk-click="mkRemoveExistingCourseExamQuestionImage(this)">حذف الصورة الحالية</button></div>`:'<input class="mk-course-exam-existing-image" type="hidden" value=""><div class="mk-course-exam-image-preview"></div>'}
      <div class="form-grid">${[0,1,2,3].map(index=>`<label>الاختيار ${String.fromCharCode(65+index)}<input class="mk-course-exam-option" maxlength="2000" value="${esc(options[index]||'')}" required></label>`).join('')}</div>
      <div class="form-grid"><label>الإجابة الصحيحة<select class="mk-course-exam-answer">${[0,1,2,3].map(index=>`<option value="${index}" ${answer===index?'selected':''}>${String.fromCharCode(65+index)}</option>`).join('')}</select></label><label>درجة السؤال<input class="mk-course-exam-points" type="number" min="1" max="100" step="1" value="${Math.max(1,Math.min(100,Number(question.points)||1))}" required></label></div>`;
