    openModal(`<div class="section-head"><div><h3>🧪 ${existing?'تعديل امتحان':'إضافة امتحان'} الدورة</h3><span class="small muted">${esc(c.title)}</span></div><button class="btn" type="button" data-mk-click="closeModal()">إغلاق</button></div><form data-mk-submit="mkSaveCourseExam(event,'${esc(String(courseId))}')"><div class="form-grid"><label>عنوان الامتحان<input id="mkCourseExamTitle" required maxlength="255" value="${esc(existing?.title||'امتحان '+c.title)}"></label><label>زمن الامتحان بالدقائق<input id="mkCourseExamDuration" type="number" min="1" max="180" value="${Math.max(1,Math.min(180,Number(existing?.duration)||30))}" required></label></div><div id="coExamQuestionsBox" class="mk-course-exam-questions"></div><button type="button" class="btn" data-mk-click="mkAddCourseExamQuestionRow()">+ إضافة سؤال نصي أو مصور</button><div class="notice" style="margin-top:12px">يمكن رفع صورة لكل سؤال بدلًا من كتابة نصه. أضف أربعة اختيارات وحدد الإجابة والدرجة.</div><button class="btn primary" style="width:100%;margin-top:14px">حفظ الامتحان ونشره</button></form>`);
    const box=document.getElementById('coExamQuestionsBox');if(existing&&Array.isArray(existing.questions)&&existing.questions.length)existing.questions.forEach(question=>window.mkAddCourseExamQuestionRow(question));else window.mkAddCourseExamQuestionRow();
