    const student=isStudent(), sid=student?String(current.id):'', enrolled=student&&courseAccess(c,sid), canWatch=isAdmin()||enrolled, pending=student&&coursePending(c,sid), prog=student?courseProgress(c,sid):[], pct=c.lessons.length?Math.round(prog.length/c.lessons.length*100):0;if(student)window.mkUpdatePointsPill(db.platformPoints?.[sid]||0);
