    window.__mkCourseLessonSelection=window.__mkCourseLessonSelection||{};let selectedIndex=Number(window.__mkCourseLessonSelection[String(c.id)]);if(!Number.isSafeInteger(selectedIndex)||selectedIndex<0||selectedIndex>=c.lessons.length)selectedIndex=Math.max(0,c.lessons.findIndex(lesson=>!lesson.locked));const selectedLesson=c.lessons[selectedIndex];
