    const selectedContent=c.videoProcessing?`<div class="notice warn">⏳ الدورة محفوظة بأمان، ويجري تحويل الفيديوهات إلى صيغة العرض. ${esc(c.videoProcessingMessage||'ستظهر للطلاب تلقائيًا بعد اكتمال التحويل.')}${c.videoError&&isAdmin()?`<br><b>${esc(c.videoError)}</b><br><button class="btn" style="margin-top:8px" data-mk-click="mkRetryCourseProcessingById('${esc(c.id)}')">إعادة محاولة تجهيز الفيديو</button>`:''}</div>`:!selectedLesson?'<div class="empty">أضف أول درس إلى هذه الدورة لبدء التعلم.</div>':selectedLesson.locked?`<div class="notice warn">🔒 ${selectedLesson.lockReason==='enrollment_required'?'سجّل أو أكمل طلب الالتحاق بالدورة لفتح هذا الدرس.':`${esc(selectedLesson.title||'هذا الدرس')} سيفتح تلقائيًا في موعد الإتاحة المحدد من الإدارة.${selectedLesson.releaseAt?`<br><b>${esc(new Date(selectedLesson.releaseAt).toLocaleString('ar-EG'))}</b>`:''}`}</div>`:!canWatch?'<div class="notice">🔒 سجل في الدورة لفتح الفيديو والدرس.</div>':`${mkVideoPlayer(c.id,selectedIndex,selectedLesson.videoRef||selectedLesson.videoUrl,selectedLesson.title)}${student&&enrolled&&!String(selectedLesson.videoRef||selectedLesson.videoUrl||'').trim()&&!prog.includes(selectedIndex)?`<button class="btn good" style="margin-top:10px" data-mk-click="mkCompleteLessonAndRefresh('${esc(c.id)}',${selectedIndex})">✓ تحديد الدرس كمكتمل</button>`:''}`;
