    window.mkSelectCourseLesson=function(courseId,index){const course=db.courses.find(item=>String(item.id)===String(courseId));if(!course||!Number.isSafeInteger(Number(index))||!course.lessons[Number(index)])return;window.__mkCourseLessonSelection[String(courseId)]=Number(index);courseDetails(courseId)};
