    window.mkVideoEngineUrl=function(path){const c=mkVideoCfg();return c.url?c.url+path:''}
    window.mkSetCoursePublishProgress=function(message){const node=document.getElementById('mkCoursePublishProgress');if(!node)return;node.textContent=String(message||'');node.classList.toggle('hidden',!message);};
    window.mkQueueVideo=async function(file,videoId,onProgress){const c=mkVideoCfg(),token=mkRuntimeGetItem('mk_video_jwt');if(!c.url||!token||!isAdmin())throw new Error('جلسة المدير أو خادم الفيديو غير متاح');if(!file)throw new Error('اختر ملف فيديو');if(file.size>1024*1024*1024)throw new Error('حجم الفيديو يتجاوز 1GB');const fd=new FormData();fd.append('video_id',String(videoId));fd.append('video',file,file.name);const data=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',c.url+'/api/v1/video/upload');xhr.setRequestHeader('Authorization','Bearer '+token);xhr.timeout=60*60*1000;xhr.upload.onprogress=event=>{if(event.lengthComputable)onProgress?.(Math.min(100,Math.round(event.loaded/event.total*100)));};xhr.onload=()=>{let body={};try{body=JSON.parse(xhr.responseText||'{}')}catch{}if(xhr.status<200||xhr.status>=300)return reject(new Error(body.message||body.error||'فشل رفع الفيديو إلى السيرفر (HTTP '+xhr.status+')'));resolve(body)};xhr.onerror=()=>reject(new Error('انقطع الاتصال أثناء رفع الفيديو؛ لم يتم حفظ الدرس.'));xhr.ontimeout=()=>reject(new Error('انتهت مهلة رفع الملف بعد ساعة؛ تحقق من اتصال الخادم وحاول مرة أخرى.'));xhr.send(fd);});if(!data?.video_id)throw new Error('لم يرجع الخادم معرّف الفيديو بعد الرفع');return{videoId:String(data.video_id),jobId:String(data.job_id||'')};};
    window.mkBackendWaitVideoJob=async function(jobId,onUpdate){const c=mkVideoCfg(),token=mkRuntimeGetItem('mk_video_jwt');if(!jobId)return{status:'completed'};if(!c.url||!token)throw new Error('انتهت جلسة الخادم؛ سجّل الدخول للمتابعة');const started=Date.now(),maxWaitMs=6*60*60*1000;let failures=0,lastMinute=0;while(Date.now()-started<maxWaitMs){await new Promise(r=>setTimeout(r,5000));let response;try{response=await fetch(c.url+'/api/v1/video/jobs/'+encodeURIComponent(jobId),{headers:{Authorization:'Bearer '+token},cache:'no-store'});if(!response.ok){if(++failures>=12)throw new Error('تعذر الاتصال بحالة تحويل الفيديو؛ أعد فتح قسم الدورات لاستكمال المتابعة');continue;}failures=0;const job=await response.json();if(job.status==='completed')return job;if(job.status==='failed')throw new Error(job.error||'فشل تحويل الفيديو بواسطة FFmpeg');const minutes=Math.floor((Date.now()-started)/60000);if(minutes>lastMinute){lastMinute=minutes;onUpdate?.(minutes,job.status);}}catch(error){if(error?.message?.includes('تعذر الاتصال بحالة تحويل الفيديو'))throw error;if(error?.message&&!/fetch|network|socket/i.test(error.message))throw error;failures++;if(failures>=12)throw new Error('تعذر الاتصال بحالة تحويل الفيديو؛ أعد فتح قسم الدورات لاستكمال المتابعة');}}throw new Error('استغرق تحويل الفيديو أكثر من 6 ساعات؛ الدورة محفوظة كقيد التجهيز ويمكن استكمال المتابعة من قسم الدورات.');};
    window.mkBackendRetryVideoJob=async function(jobId){const c=mkVideoCfg(),token=mkRuntimeGetItem('mk_video_jwt');if(!c.url||!token||!isAdmin())throw new Error('صلاحية المدير أو خادم الفيديو غير متاح');const response=await fetch(c.url+'/api/v1/video/jobs/'+encodeURIComponent(jobId)+'/retry',{method:'POST',headers:{Authorization:'Bearer '+token},cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||'تعذرت إعادة محاولة تحويل الفيديو');return data;};
    window.mkBackendUploadVideo=async function(file,videoId){if(!file)return null;window.mkSetCoursePublishProgress('جارٍ رفع الفيديو إلى الخادم...');const queued=await window.mkQueueVideo(file,videoId);if(!queued.jobId)return queued.videoId;window.mkSetCoursePublishProgress('تم رفع الفيديو. جارٍ تحويله إلى صيغة العرض على الموقع...');await window.mkBackendWaitVideoJob(queued.jobId,(minutes)=>window.mkSetCoursePublishProgress('الفيديو قيد التحويل منذ '+minutes+' دقيقة.'));return queued.videoId;};
    window.mkDeviceFingerprint=function(){const name='mk_device_fingerprint',match=document.cookie.split('; ').find(x=>x.startsWith(name+'='));let v=match?decodeURIComponent(match.slice(name.length+1)):'';if(!/^[A-Za-z0-9_-]{16,256}$/.test(v)){v='mkd_'+crypto.randomUUID().replaceAll('-','');document.cookie=name+'='+encodeURIComponent(v)+'; Path=/; Max-Age=63072000; SameSite=Strict'+(location.protocol==='https:'?'; Secure':'');}return v};window.mkBackendAuthLogin=async function(u,pass,remember=true){const c=mkVideoCfg();window.mkBackendLastUserId='';window.mkBackendLastRole='';window.mkBackendAuthError='';if(!c.url||!u||!pass){window.mkBackendAuthError='بيانات الدخول أو عنوان خادم المنصة غير مكتمل.';return false;}try{const res=await fetch(c.url+'/api/v1/auth/login',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:String(u.email||u.id),password:String(pass),parent_phone:String(u.parentPhone||''),remember:remember!==false,device_fingerprint:window.mkDeviceFingerprint()})});const data=await res.json().catch(()=>({}));if(!res.ok){const message=String(data?.message||data?.error||'تعذر تسجيل الدخول إلى خادم المنصة.');window.mkBackendAuthError=message==='invalid credentials or inactive account'?'بيانات الدخول غير صحيحة أو الحساب غير مفعّل.':message==='invalid credentials'?'بيانات الدخول غير صحيحة.':message;throw new Error(window.mkBackendAuthError);}if(data?.token){mkRuntimeSetItem('mk_video_jwt',data.token);window.mkBackendLastUserId=String(data.user_id||'');window.mkBackendLastRole=String(data.role||'');}if(!data?.token)window.mkBackendAuthError='لم يُرجع الخادم جلسة دخول صالحة.';return !!data?.token}catch(e){mkRuntimeRemoveItem('mk_video_jwt');window.mkBackendLastUserId='';window.mkBackendLastRole='';if(!window.mkBackendAuthError)window.mkBackendAuthError='تعذر الاتصال بخادم المنصة. تحقق من تشغيله ثم أعد المحاولة.';console.warn('MK backend auth unavailable',e);return false;}};
    window.mkBackendGetAuditLogs=async function(limit=200){const c=mkVideoCfg(),token=mkRuntimeGetItem('mk_video_jwt');if(!c.url||!token)throw new Error('جلسة الإدارة غير متاحة');const response=await fetch(c.url+'/api/v1/admin/audit-logs?limit='+encodeURIComponent(limit),{headers:{Authorization:'Bearer '+token},cache:'no-store'});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||'تعذر تحميل سجل النشاط');return Array.isArray(data.entries)?data.entries:[];};
