    window.mkRefreshActivityLog=async function(){const root=document.getElementById('mkActivityLogRows'),status=document.getElementById('mkActivityLogStatus');if(!root)return;if(status)status.textContent='جارٍ تحميل أحدث الأنشطة…';try{const entries=await window.mkBackendGetAuditLogs(300);if(!root.isConnected)return;const labels={login:'تسجيل دخول',logout:'تسجيل خروج',self_register:'إنشاء حساب',platform_sync:'مزامنة الحسابات'};root.innerHTML=entries.map(row=>{let time='—';try{time=new Date(row.created_at).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'})}catch{}return `<tr><td><b>${esc(row.actor_name||row.actor_id||'غير معروف')}</b><br><span class="small muted">${esc(row.email||row.actor_id||'')}</span></td><td>${esc(({admin:'مدير',student:'طالب',parent:'ولي أمر'})[row.role]||row.role||'—')}</td><td><span class="chip ${row.action==='login'?'good':row.action==='logout'?'warn':''}">${esc(labels[row.action]||row.action||'نشاط')}</span></td><td>${esc(row.details||'—')}</td><td>${esc(time)}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">لا توجد أحداث مسجلة بعد.</td></tr>';if(status)status.textContent=`آخر ${entries.length} حدث مسجل على الخادم.`}catch(error){if(status)status.textContent=error.message||'تعذر تحميل السجل';root.innerHTML='<tr><td colspan="5" class="empty">تعذر تحميل سجل النشاط. تحقق من اتصال الخادم.</td></tr>'}};
    pages.activityLog=function(){if(current?.role!=='admin')return forbidden();setTimeout(()=>void window.mkRefreshActivityLog(),0);return `<div class="grid"><div class="card"><div class="section-head"><div><h3>🧾 سجل الدخول والنشاط</h3><span id="mkActivityLogStatus" class="small muted">يعرض أوقات إنشاء الحساب وتسجيل الدخول والخروج وأهم إجراءات المنصة حسب توقيت جهازك.</span></div><button class="btn" data-mk-click="mkRefreshActivityLog()">تحديث</button></div><div class="table-wrap"><table class="table"><thead><tr><th>الحساب</th><th>الدور</th><th>الحدث</th><th>التفاصيل</th><th>التاريخ والوقت</th></tr></thead><tbody id="mkActivityLogRows"><tr><td colspan="5" class="empty">جارٍ تحميل السجل…</td></tr></tbody></table></div><div class="small muted" style="margin-top:10px">وقت تسجيل الخروج يظهر عند استخدام زر «تسجيل الخروج». إغلاق المتصفح يظل مسجل الدخول لتسهيل الرجوع للحساب.</div></div></div>`};
