    window.mkVideoEngineSettings=function(){if(!isAdmin())return forbidden();openModal('<div class="section-head"><div><h3>🎬 محرك فيديو MK</h3><span class="small muted">افحص جاهزية تحويل الفيديو على خادم المنصة.</span></div><button class="btn" data-mk-click="closeModal()">إغلاق</button></div><div class="notice good" style="margin:12px 0">🔐 رفع الفيديو ومزامنة بياناته محميان بجلسة المدير.</div><section class="mk-video-diagnostic"><div><b>فحص تحويل الفيديو</b><p class="small muted">اختبر أن الخادم يستطيع تشغيل FFmpeg قبل رفع دورة جديدة.</p></div><button type="button" class="btn" data-mk-click="mkCheckVideoEngine(this)">اختبار FFmpeg</button><div id="mkVideoEngineStatus" class="notice" role="status" aria-live="polite">لم يتم الفحص بعد.</div></section>')};
