    const oldSettings=pages.settings;
    pages.settings=function(){const base=oldSettings?oldSettings():'<div></div>';if(!isAdmin())return base;return base+'<div class="card" style="margin-top:15px"><div class="section-head"><div><h3>🎬 Video Engine</h3><span class="small muted">رفع الفيديو على السيرفر، تحويله إلى HLS عبر Queue + FFmpeg، والتحقق من صلاحية الطالب قبل كل مشاهدة.</span></div><span class="chip '+(mkVideoEngineConfigured()?'good':'warn')+'">'+(mkVideoEngineConfigured()?'متصل':'غير مربوط')+'</span></div><p class="small muted">عنوان خادم المنصة مدمج في التطبيق ويُستخدم تلقائيًا لرفع المحتوى وتشغيل الفيديو.</p><button class="btn primary" data-mk-click="mkVideoEngineSettings()">⚙️ فحص معالجة الفيديو</button> <button class="btn" data-mk-click="mkSyncUsersAndNotify()">🔄 مزامنة الحسابات</button></div><div class="card" style="margin-top:15px"><h3>🔑 استعادة حساب المستخدم</h3><p class="small muted">تحقق من هوية صاحب الحساب خارج المنصة أولًا. تغيير كلمة المرور سيُنهي الجلسات المفتوحة على أجهزته.</p><form data-mk-submit="mkAdminResetAccountPassword(event)"><div class="form-grid"><label>معرّف الحساب أو البريد الإلكتروني<input id="mkResetAccountId" autocomplete="off" required></label><label>كلمة المرور المؤقتة الجديدة<input id="mkResetAccountPass" type="password" minlength="8" maxlength="1024" autocomplete="new-password" required></label><label>تأكيد كلمة المرور<input id="mkResetAccountConfirm" type="password" minlength="8" maxlength="1024" autocomplete="new-password" required></label></div><button id="mkResetAccountSubmit" class="btn primary" style="margin-top:10px">تغيير كلمة المرور وإنهاء الجلسات</button></form><div class="notice warn" style="margin-top:12px">لا ترسل كلمة المرور في رسالة عامة. سلّمها لصاحب الحساب بطريقة آمنة واطلب منه تغييرها بعد الدخول.</div></div>';}
