    const hlsAwarePlay=window.mkPlay;
    window.mkPlay=async function(id){const video=mkGetVideo(id);if(!video)return;if(video.dataset.mkLocked==='1')return toast('⛔ انتهت مشاهدات هذا الفيديو — الحد الأقصى 3 مشاهدات');const ref=String(video.dataset.mkVideoRef||'');if(!ref.startsWith('hls:video-engine:'))return hlsAwarePlay(id);if(video.dataset.mkHls==='1'){if(video.dataset.mkHlsReady!=='1'){video.dataset.mkHlsAutoPlay='1';return toast('جارٍ تحميل الفيديو من الخادم…');}return hlsAwarePlay(id);}if(video.dataset.mkViewGranted!=='1'){const player=document.getElementById(id),lesson=String(player?.dataset?.mkCourseLesson||'').split('|');if(lesson.length!==2)return toast('تعذر تحديد الدرس المرتبط بالفيديو.');try{const allowed=await window.mkRegisterView(lesson[0],Number(lesson[1]));if(!allowed)return;video.dataset.mkViewGranted='1';video.dataset.mkCounted='1';}catch(error){return toast(error?.message||'تعذر التحقق من صلاحية مشاهدة الفيديو.');}}try{const source=await window.mkVideoSource(ref);if(window.Hls&&window.Hls.isSupported()){const controller=new window.Hls({enableWorker:true});video.__mkHlsController=controller;video.dataset.mkHls='1';video.dataset.mkHlsReady='0';video.dataset.mkHlsAutoPlay='1';controller.on(window.Hls.Events.MANIFEST_PARSED,()=>{video.dataset.mkHlsReady='1';window.mkPopulateVideoQualities?.(video,controller.levels);if(video.dataset.mkHlsAutoPlay==='1'){video.dataset.mkHlsAutoPlay='0';video.play().catch(()=>toast('تم تجهيز الفيديو؛ اضغط زر التشغيل مرة أخرى إذا لم يبدأ.'));}});controller.on(window.Hls.Events.ERROR,(_event,data)=>{if(!data?.fatal)return;const status=Number(data?.response?.code||0),message=status===404?'الفيديو غير موجود على الخادم أو لم يكتمل تحويله.':status===401||status===403?'انتهت صلاحية تشغيل الفيديو؛ أعد تحميل صفحة الدورة وسجّل الدخول من جديد.':data?.type==='networkError'?'تعذر الاتصال بخادم الفيديو؛ تحقق أن خادم المنصة يعمل.':'تعذر فك ملف الفيديو. تحقق من اكتمال رفعه وتحويله على الخادم.';video.dataset.mkHls='0';video.dataset.mkHlsReady='0';video.__mkHlsController?.destroy();video.__mkHlsController=null;toast(message);});controller.on(window.Hls.Events.MEDIA_ATTACHED,()=>controller.loadSource(source));controller.attachMedia(video);return;}if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=source;video.dataset.mkHls='1';video.dataset.mkHlsReady='1';video.play().catch(()=>toast('تم تجهيز الفيديو؛ اضغط زر التشغيل مرة أخرى إذا لم يبدأ.'));return;}throw new Error('المتصفح الحالي لا يدعم تشغيل فيديو HLS. حدّث Chrome أو استخدم متصفحًا حديثًا.');}catch(error){toast(error?.message||'تعذر تحميل الفيديو من خادم المنصة.');}};
    const oldPlayer=window.mkVideoPlayer;
    window.mkPopulateVideoQualities=function(video,levels){const select=document.getElementById(String(video?.id||'').replace(/_v$/,'_quality'));if(!select)return;const rows=Array.isArray(levels)?levels:[];const options=rows.map((level,index)=>({index,height:Number(level?.height)||0,bitrate:Number(level?.bitrate)||Number(level?.maxBitrate)||0})).filter(level=>Number.isInteger(level.index));select.innerHTML='<option value="-1">تلقائي</option>'+options.map(level=>`<option value="${level.index}">${level.height?`${level.height}p`:`جودة ${level.index+1}`}${level.bitrate?` • ${Math.round(level.bitrate/1000)} ك.بت/ث`:''}</option>`).join('');const selected=String(video.dataset.mkQuality||'-1');select.value=options.some(item=>String(item.index)===selected)?selected:'-1';select.disabled=options.length<2;select.title=options.length<2?'هذا الفيديو يحتوي على جودة واحدة فقط':'اختر جودة التشغيل';};
    window.mkVideoQuality=function(id,value){const video=mkGetVideo(id),controller=video?.__mkHlsController,select=document.getElementById(String(video?.id||'').replace(/_v$/,'_quality'));if(!video||!controller||!Array.isArray(controller.levels))return toast('تظهر خيارات الجودة بعد تحميل فيديو متعدد الجودات');const level=String(value)==='-1'?-1:Number(value);if(level!==-1&&(!Number.isInteger(level)||level<0||level>=controller.levels.length))return toast('الجودة المحددة غير متاحة');controller.nextLevel=level;video.dataset.mkQuality=String(level);if(select)select.value=String(level);};
    window.mkVideoPlayer=function(courseId,index,videoRef,title){let html=oldPlayer(courseId,index,videoRef,title);html=html.replace(/class="mk-player" id="([^"]+)"/,'class="mk-player" id="$1" data-mk-course-id="'+esc(courseId)+'" data-mk-course-lesson="'+String(courseId).replace(/[^a-zA-Z0-9_-]/g,'_')+'|'+index+'"');if(String(videoRef||'').startsWith('hls:')){html=html.replace(/ src="hls:[^"]*"/,'');const safeId='mkvid_'+String(courseId).replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+index;html=html.replace('<select class="btn mk-player-control mk-player-speed"',`<select id="${safeId}_quality" class="btn mk-player-control mk-player-quality" aria-label="جودة الفيديو" title="خيارات الجودة تظهر بعد تحميل الفيديو" disabled data-mk-change="mkVideoQuality('${safeId}',this.value)"><option value="-1">الجودة: تلقائي</option></select><select class="btn mk-player-control mk-player-speed"`);}return html};
